#!/usr/bin/env python3
"""Regenerate ten technical figures exclusively from recorded original paceval
results. Fig 1 is a schematic; the title image is a concept illustration.
No arbitrary synthetic scientific values are generated by this script.
"""
from pathlib import Path
import argparse,csv,math
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch, FancyArrowPatch
from matplotlib import colors
from collections import defaultdict
NAVY='#172b44';TEAL='#008f8f';GREEN='#1d9f79';MAG='#995dc1';PINK='#e75b79';BLUE='#2f75b5';GOLD='#c68c24';GRAY='#5c6a78'
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.titlesize':13,'axes.titleweight':'bold','axes.labelsize':10,'figure.facecolor':'white','axes.facecolor':'white','axes.spines.top':False,'axes.spines.right':False,'savefig.facecolor':'white'})
def read(path):
 with open(path,newline='') as f:return list(csv.DictReader(f))
def num(r,k):return float(r[k])
def save(f,dir,index,name,caption):
 f.savefig(dir/f'{index:02d}_{name}.png',dpi=230,bbox_inches='tight',pad_inches=.19)
 f.savefig(dir/f'{index:02d}_{name}.pdf',bbox_inches='tight',pad_inches=.1)
 plt.close(f)
 return [index,name,caption,'results-derived' if index>1 else 'research architecture schematic']
def main(root):
 root=Path(root);out=root/'figures';p=root/'results';out.mkdir(exist_ok=True)
 summaries=read(p/'scenario_summary.csv'); profiles=read(p/'concentration_profiles.csv');mass=read(p/'mass_balance.csv');probes=read(p/'graph_probe.csv');scores=read(p/'score_variants.csv');manifest=[]
 # Fig 1 — architecture schematic, no model output.
 f,ax=plt.subplots(figsize=(12.5,3.6));ax.set_xlim(0,12);ax.set_ylim(0,4);ax.axis('off')
 steps=[('Synthetic feed & flow','A, B, C; u; D; kf; kr'),('Finite-volume host','state, mesh, boundaries'),('paceval graphs','rates, full updates, scores'),('Independent audit','80-digit oracle, balance')]
 for i,(title,sub) in enumerate(steps):
  x=.2+i*3.05;rect=FancyBboxPatch((x,1.25),2.65,1.45,boxstyle='round,pad=0.12,rounding_size=.18',edgecolor=TEAL if i==2 else NAVY,linewidth=1.8,facecolor='#e4faf5' if i==2 else '#f2f6fa');ax.add_patch(rect)
  ax.text(x+1.325,2.22,title,ha='center',va='center',weight='bold',color=NAVY,fontsize=10)
  ax.text(x+1.325,1.70,sub,ha='center',va='center',color=GRAY,fontsize=8.3)
  if i<3:ax.add_patch(FancyArrowPatch((x+2.74,1.96),(x+3.04,1.96),arrowstyle='-|>',mutation_scale=15,color=TEAL,linewidth=2))
 ax.set_title('Microreactor digital-research workflow',pad=14,color=NAVY)
 manifest.append(save(f,out,1,'workflow','Schematic of the simulated 1-D microreactor, actual paceval graph evaluation and separate independent verification.'))
 # Fig 2 — spatial species profiles for model v1 with stronger kinetics
 fig,ax=plt.subplots(figsize=(9.2,5.5));colors3={'A_mmol_per_L':TEAL,'B_mmol_per_L':GOLD,'C_mmol_per_L':MAG};times=sorted(set(num(x,'time_s') for x in profiles if x['scenario_id']=='3'));selected=[times[len(times)//4],times[len(times)//2],times[-1]]
 for ti,ls in zip(selected,[':', '--','-']):
  dat=sorted((x for x in profiles if x['scenario_id']=='3' and abs(num(x,'time_s')-ti)<1e-8),key=lambda x:num(x,'x_mm'))
  for field,c in colors3.items():ax.plot([num(x,'x_mm') for x in dat],[num(x,field) for x in dat],linestyle=ls,color=c,lw=2,alpha=.90,label=f'{field[0]} · {ti:g} s')
 ax.set(xlabel='Distance along channel (mm)',ylabel='Concentration (mmol/L)',ylim=(-.04,1.04),title='Reagent-to-product evolution along the channel');ax.legend(ncol=3,fontsize=8.5);ax.grid(alpha=.15)
 manifest.append(save(fig,out,2,'spatial_species_profiles','Actual paceval A, B, C profiles at three times for scenario 3 (v1, u=0.25 mm/s, kf=0.032).'))
 # Fig 3 — 3D spatiotemporal surface
 rows=[x for x in profiles if x['scenario_id']=='3'];times=sorted(set(num(x,'time_s') for x in rows));positions=sorted(set(num(x,'x_mm') for x in rows));vals={(num(r,'time_s'),num(r,'x_mm')):num(r,'C_mmol_per_L') for r in rows};T,X=np.meshgrid(times,positions,indexing='ij');Z=np.array([[vals[(t,x)] for x in positions] for t in times]);
 fig=plt.figure(figsize=(10.7,6.3));ax=fig.add_subplot(111,projection='3d');surf=ax.plot_surface(X,T,Z,cmap='viridis',linewidth=0,antialiased=True,alpha=.98);fig.colorbar(surf,ax=ax,shrink=.62,pad=.08,label='C (mmol/L)');ax.set(xlabel='Channel x (mm)',ylabel='Time (s)',zlabel='Product C (mmol/L)',title='Paceval-computed product concentration in space and time');ax.view_init(elev=25,azim=-61)
 manifest.append(save(fig,out,3,'product_spacetime_3d','3-D spatiotemporal surface from stored finite-volume C values computed by original paceval update graphs.'))
 # Fig 4 — reacted fraction vs velocity
 fig,ax=plt.subplots(figsize=(9.1,5.3));
 for v,style,col in [(1,'-',BLUE),(2,'--',PINK)]:
  for k,marker in [(.018,'o'),(.032,'s')]:
   subset=sorted([r for r in summaries if int(r['model_version'])==v and abs(num(r,'kf_L_per_mmol_s')-k)<1e-9],key=lambda a:num(a,'u_mm_per_s'))
   ax.plot([num(r,'u_mm_per_s') for r in subset],[num(r,'outlet_stoichiometric_reacted_fraction') for r in subset],linestyle=style,marker=marker,color=col,lw=2,markersize=8,label=f'v{v}, kf={k:.3f}')
 ax.set(xlabel='Mean channel velocity (mm/s)',ylabel='Stoichiometric reacted fraction at outlet',ylim=(0,0.8),title='Reaction extent as flow and chemistry change');ax.grid(alpha=.17);ax.legend(fontsize=9)
 manifest.append(save(fig,out,4,'reacted_fraction_flow','Outlet reaction extent for both kinetic versions and forward-rate settings (t=144 s).'))
 # Fig 5 — split 2D heatmap, both versions
 fig,axs=plt.subplots(1,2,figsize=(11.3,4.6),sharey=True,constrained_layout=True)
 for v,ax in [(1,axs[0]),(2,axs[1])]:
  vel=[.25,.40,.55];rates=[.018,.032];M=np.array([[num(next(r for r in summaries if int(r['model_version'])==v and abs(num(r,'u_mm_per_s')-u)<1e-10 and abs(num(r,'kf_L_per_mmol_s')-k)<1e-10),'C_out_mmol_per_L') for u in vel]for k in rates]);
  im=ax.imshow(M,cmap='magma',vmin=0,vmax=.75,aspect='auto');ax.set_xticks(range(3),[f'{x:g}' for x in vel]);ax.set_yticks([0,1],[f'{x:g}' for x in rates]);ax.set_title(f'Kinetic model v{v}',color=NAVY);ax.set_xlabel('Velocity (mm/s)')
  for i in range(2):
   for j in range(3):ax.text(j,i,f'{M[i,j]:.3f}',color='white',ha='center',va='center',weight='bold')
 axs[0].set_ylabel('kf (L/[mmol s])');fig.suptitle('Product outlet concentration across operating points',weight='bold',color=NAVY,y=1.105);fig.colorbar(im,ax=axs.ravel().tolist(),shrink=.8,label='C (mmol/L)',pad=.025,fraction=.035)
 manifest.append(save(fig,out,5,'outlet_product_parameter_map','End-of-run product concentration across twelve original paceval scenarios.'))
 # Fig 6 — reaction revisions effect
 fig,ax=plt.subplots(figsize=(9.2,5.0));xs=[];ys=[];labels=[]
 for u in [.25,.4,.55]:
  for k in [.018,.032]:
   a=next(r for r in summaries if int(r['model_version'])==1 and abs(num(r,'u_mm_per_s')-u)<1e-10 and abs(num(r,'kf_L_per_mmol_s')-k)<1e-10)
   b=next(r for r in summaries if int(r['model_version'])==2 and abs(num(r,'u_mm_per_s')-u)<1e-10 and abs(num(r,'kf_L_per_mmol_s')-k)<1e-10)
   xs.append(f'u {u:.2f}\nk {k:.3f}');ys.append(num(b,'C_out_mmol_per_L')-num(a,'C_out_mmol_per_L'))
 ax.bar(range(len(xs)),ys,color=[PINK if x<0 else TEAL for x in ys]);ax.axhline(0,color=GRAY,lw=1);ax.set_xticks(range(len(xs)),xs,fontsize=9);ax.set(ylabel='C outlet (v2 − v1), mmol/L',title='Controlled kinetic-model change: local saturation');ax.grid(axis='y',alpha=.15)
 manifest.append(save(fig,out,6,'versioned_reaction_outcome','Paired change in product concentration after switching the active kinetics to a saturation-dependent model.'))
 # Fig 7 — physical mass conservation
 fig,ax=plt.subplots(figsize=(9.1,5.2));m=sorted([r for r in mass if r['scenario_id']=='3'],key=lambda r:num(r,'time_s'));t=[num(x,'time_s') for x in m];ax.plot(t,[num(r,'domain_mass_AplusC') for r in m],lw=2.5,color=TEAL,label='Domain A + C');ax.plot(t,[num(r,'integrated_net_boundary_AplusC') for r in m],lw=1.5,ls='--',color=NAVY,label='Integrated net boundary A + C');ax.plot(t,[num(r,'domain_mass_BplusC') for r in m],lw=2.3,color=PINK,label='Domain B + C');ax.plot(t,[num(r,'integrated_net_boundary_BplusC') for r in m],lw=1.4,ls='--',color=MAG,label='Integrated net boundary B + C');ax.set(xlabel='Time (s)',ylabel='Length-integrated concentration (mmol·mm/L)',title='Reaction invariants and integrated boundary transport');ax.grid(alpha=.15);ax.legend(fontsize=8)
 manifest.append(save(fig,out,7,'stoichiometric_inventory','Conservative species-pair inventories and cumulative boundary transport for the same paceval trajectory.'))
 # Fig 8 — sensitivities from genuinely recorded paceval probe output
 sub=[r for r in probes if r['graph_id']=='d_rate_dA_v2' and int(r['scenario_id'])==4 and num(r,'A')>.015];sub2=[r for r in probes if r['graph_id']=='reaction_rate_v2' and int(r['scenario_id'])==4 and num(r,'A')>.015]
 fig,ax=plt.subplots(figsize=(9.3,5.2));ax.scatter([num(r,'A') for r in sub],[num(r,'paceval_result') for r in sub],c=[num(r,'B') for r in sub],cmap='viridis',s=37,edgecolor='none');scat=ax.collections[-1];fig.colorbar(scat,ax=ax,label='Local B (mmol/L)');ax.set(xlabel='Local A (mmol/L)',ylabel='∂reaction rate / ∂A (s⁻¹)',title='Real paceval sensitivity values, kinetic model v2');ax.grid(alpha=.15)
 manifest.append(save(fig,out,8,'local_kinetic_sensitivities','Recorded analytical paceval derivative samples, colored by local B concentration (scenario 4).'))
 # Fig 9 — dimensionless plane with outcomes
 fig,ax=plt.subplots(figsize=(9.3,5.3));
 for v,marker in [(1,'o'),(2,'s')]:
  s=[r for r in summaries if int(r['model_version'])==v];sp=ax.scatter([num(r,'Pe') for r in s],[num(r,'Da_nominal') for r in s],c=[num(r,'outlet_stoichiometric_reacted_fraction') for r in s],cmap='viridis',vmin=0,vmax=.8,s=170,marker=marker,edgecolors='white',linewidths=.7,label=f'v{v}')
 ax.set(xlabel='Channel Péclet number uL/D (−)',ylabel='Nominal Damköhler number kf·Bin·L/u (−)',title='Reactor regimes and reacted fraction');ax.grid(alpha=.15);ax.legend();fig.colorbar(sp,ax=ax,label='Outlet reacted fraction (−)')
 manifest.append(save(fig,out,9,'peclet_damkohler_map','Dimensionless operating-point map with paceval-derived outlet reaction extent.'))
 # Fig 10 — 12 weighted score variants for two matched scenarios
 fig,ax=plt.subplots(figsize=(9.6,5.1));
 for sid,col in [(3,BLUE),(4,PINK)]:
  s=sorted([r for r in scores if int(r['scenario_id'])==sid],key=lambda r:int(r['graph_id'].split('_')[-1]));ax.plot([int(r['graph_id'].split('_')[-1]) for r in s],[num(r,'score_value') for r in s],marker='o',lw=2.3,color=col,label=f'Scenario {sid}, model v{1 if sid==3 else 2}')
 ax.set(xlabel='Formula version of illustrative weighted score',ylabel='Composite score (dimensionless synthetic index)',title='Programmable assessment formulas in original paceval');ax.set_xticks(range(1,13));ax.legend();ax.grid(alpha=.18)
 manifest.append(save(fig,out,10,'programmable_composite_scores','Twelve actual reusable composite-score graph outputs for matched operating settings.'))
 with open(p/'figure_manifest.csv','w',newline='') as f:
  w=csv.writer(f);w.writerow(['figure_number','stem','caption','provenance']);w.writerows(manifest)
 print('Ten PNG and vector-PDF scientific figures generated directly from the original paceval computation outputs.')
if __name__=='__main__':
 ap=argparse.ArgumentParser();ap.add_argument('--root',type=Path,default=Path(__file__).resolve().parent.parent);args=ap.parse_args();main(args.root)
